#!/usr/bin/env node

/*
 * Prepare an extracted upstream Bangumi source tree for the unsigned IPA build.
 *
 * Two phases, because the native project is generated by Expo and that needs
 * node_modules:
 *
 *   source  - activate the IPA dependency set and rewrite JavaScript sources
 *             (run before `yarn install`)
 *   native  - regenerate ios/ with `expo prebuild` and apply the native tweaks
 *             (run after `yarn install` and patch-package)
 *
 * The tag's checked-in ios/ directory is deliberately thrown away. It was
 * generated by an Expo 52-era prebuild: EXAppDelegateWrapper used to subclass
 * RCTAppDelegate, which is what created the window and started React Native.
 * On Expo 54 it does neither, so that AppDelegate compiles fine and then
 * launches to nothing at all.
 *
 * Every rewrite either applies or fails the build. The inline `replaceInFile`
 * helper this script replaces did nothing when upstream moved the code, which
 * is how 8.39.0 spent four days failing eleven minutes deep inside xcodebuild
 * instead of failing in this step.
 */

import { execFileSync, spawnSync } from 'node:child_process'
import { appendFileSync, copyFileSync, existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const SOURCE_EXTENSIONS = new Set(['.ts', '.tsx', '.js', '.jsx', '.swift'])

/** Expo SDK major that this script was written against. */
const EXPECTED_EXPO_MAJOR = 57

/**
 * The newest iOS SDK this project is known to produce a working app with.
 *
 * iOS 27 makes "app does not adopt the UIScene lifecycle" a fatal runtime issue
 * for anything linked against its SDK -- EXC_BREAKPOINT inside
 * _UIApplicationEvaluateRuntimeIssueForNoSceneLifecycleAdoption, before any app
 * code runs. Expo 54 has not adopted scenes (ExpoAppDelegate.swift still reads
 * "TODO: - Configuring and Discarding Scenes") and a bare UIApplicationSceneManifest
 * does not satisfy the check, so there is no fix available at this SDK level.
 * Fail the build loudly rather than shipping an IPA that cannot launch.
 */
const MAX_SUPPORTED_IOS_SDK_MAJOR = 26

/**
 * Packages the IPA dependency set is missing but the source needs. Empty while
 * the set matches master; entries here must match EXPECTED_EXPO_MAJOR.
 */
const DEPENDENCY_OVERRIDES = {}

/**
 * Rewrites, applied across every file under the phase's scan roots.
 *
 * - `when`      decides whether the rewrite is needed for this dependency set.
 *               A rewrite that is not needed is skipped and logged, never guessed.
 * - `edits`     literal from -> to pairs. Idempotent: re-running is a no-op.
 * - `residual`  (optional) must not match anywhere after the rewrite ran. It
 *               targets module specifiers only, so prose mentioning the package
 *               does not trip it.
 * - `satisfied` (optional) recognises a tree that already has the change, so a
 *               rewrite that also landed upstream does not double-apply.
 */
function sourceRewrites(deps) {
  return [
    {
      id: 'opencc-subpath',
      why: 'Metro only resolves package.json "exports" subpaths by default from RN 0.79',
      when: () => Boolean(deps['opencc-js']) && reactNativeMinor(deps['react-native']) < 79,
      edits: [
        ["'opencc-js/core'", "'opencc-js/dist/esm-lib/core'"],
        ["'opencc-js/from/cn'", "'opencc-js/dist/esm-lib/from/cn'"],
        ["'opencc-js/to/hk'", "'opencc-js/dist/esm-lib/to/hk'"],
        ["'opencc-js/to/tw'", "'opencc-js/dist/esm-lib/to/tw'"]
      ],
      residual: /['"]opencc-js\/(?!dist\/)/
    },
    {
      id: 'expo-file-system-legacy',
      why: 'the legacy subpath only exists from expo-file-system 19 (Expo 54); on 18 the classic API is the package root',
      when: () => majorOf(deps['expo-file-system']) < 19,
      edits: [
        ["'expo-file-system/legacy'", "'expo-file-system'"],
        ['"expo-file-system/legacy"', '"expo-file-system"']
      ],
      residual: /['"]expo-file-system\/legacy['"]/
    },
    {
      id: 'react-native-worklets',
      why: 'react-native-worklets is a reanimated 4 package; on reanimated 3 the scheduler lives in reanimated itself',
      when: () => !deps['react-native-worklets'],
      edits: [
        [
          "(require('react-native-worklets') as typeof import('react-native-worklets')).scheduleOnRN",
          'reanimatedScheduleOnRN'
        ],
        [
          "(require('react-native-worklets') as typeof import('react-native-worklets')).scheduleOnUI",
          'reanimatedScheduleOnUI'
        ]
      ],
      residual: /(?:from|require\s*\(|import\s*\()\s*['"]react-native-worklets['"]/
    }
  ]
}

/** Applied to the AppDelegate that `expo prebuild` generates. */
function nativeRewrites() {
  return [
    {
      id: 'image-disk-cache',
      why: 'the app configures a 200MB shared URLCache for images; prebuild does not know about it',
      when: () => true,
      satisfied: source => source.includes('bnm_image_cache'),
      edits: [
        [
          '    let delegate = ReactNativeDelegate()',
          [
            "    // 配置图片磁盘缓存, 配合 source.cache = 'force-cache' 使用",
            '    URLCache.shared = URLCache(',
            '      memoryCapacity: 50 * 1024 * 1024,',
            '      diskCapacity: 200 * 1024 * 1024,',
            '      diskPath: "bnm_image_cache"',
            '    )',
            '',
            '    let delegate = ReactNativeDelegate()'
          ].join('\n')
        ]
      ]
    }
  ]
}

function fail(message) {
  console.error(`::error::${message}`)
  process.exit(1)
}

function notice(message) {
  console.log(`::notice::${message}`)
}

function readJson(path) {
  return JSON.parse(readFileSync(path, 'utf8'))
}

function writeJson(path, value) {
  writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`)
}

function majorOf(range) {
  const match = String(range || '').match(/(\d+)/)
  return match ? Number(match[1]) : 0
}

/** react-native versions are 0.MINOR.PATCH, so the minor is the interesting number. */
function reactNativeMinor(range) {
  const match = String(range || '').match(/^\D*(\d+)\.(\d+)/)
  return match ? Number(match[2]) : 0
}

function exportEnv(name, value) {
  console.log(`${name}=${value}`)
  if (process.env.GITHUB_ENV) {
    appendFileSync(process.env.GITHUB_ENV, `${name}=${value}\n`)
  }
}

function collectFiles(roots) {
  const files = []

  const walk = path => {
    if (!existsSync(path)) return

    const stats = statSync(path)
    if (stats.isFile()) {
      const dot = path.lastIndexOf('.')
      if (dot > -1 && SOURCE_EXTENSIONS.has(path.slice(dot))) files.push(path)
      return
    }

    if (!stats.isDirectory()) return

    for (const entry of readdirSync(path)) {
      if (entry === 'node_modules' || entry === 'Pods' || entry.startsWith('.')) continue
      walk(join(path, entry))
    }
  }

  roots.forEach(walk)

  if (!files.length) fail(`No files found under ${roots.join(', ')}`)

  return files
}

/** Swap the root package.json / patches / babel config over to the IPA environment. */
function switchToIpaEnvironment() {
  const before = readJson('package.json')

  execFileSync('node', ['packages/env.js', 'ipa'], { stdio: 'inherit' })

  const after = readJson('package.json')
  if (after.name !== 'ipa') {
    fail(`packages/env.js ipa did not activate the IPA package set (package.json name is "${after.name}")`)
  }

  return { masterPackageJson: before, ipaPackageJson: after }
}

/**
 * app.json is the single source of the app's own version: src/constants/env.ts
 * imports it for VERSION_GITHUB_RELEASE (shown in the UI and sent as the
 * User-Agent), and Info.plist plus the embedded Expo config are synced from it.
 *
 * A tag cut without bumping it therefore ships an app that calls itself by the
 * previous version -- 8.39.3 reports 8.39.2. That is not cosmetic: the AltStore
 * source lists the tag, the installed app reports app.json, and AltStore
 * compares the two, so the update prompt never clears.
 *
 * The tag is the release identity here, so it wins.
 */
function syncAppVersionToTag() {
  const appJson = readJson('app.json')
  const current = appJson.expo?.version
  if (!current) fail('app.json is missing expo.version')

  const tag = (process.env.UPSTREAM_TAG || '').trim()
  if (!tag) {
    notice(`UPSTREAM_TAG is not set; building with app.json's own version ${current}.`)
    return current
  }

  if (current === tag) {
    console.log(`app.json version matches the tag (${tag})`)
    return current
  }

  appJson.expo.version = tag
  writeJson('app.json', appJson)
  notice(
    `app.json declared ${current} but this is tag ${tag}; using ${tag}. ` +
      'android.versionCode is left alone -- it is the Play Store build number and this build does not use it.'
  )

  return tag
}

/**
 * The IPA dependency set is maintained in this repository, not in the upstream
 * tag. A tag carries whatever packages/ipa/package.json looked like when it was
 * cut, which is how this environment sat on Expo 52 from February to August
 * while master moved to 54. IPA_PACKAGE_JSON points at the maintained copy;
 * without it the tag's own set is used.
 */
function overrideIpaPackageJson() {
  const override = process.env.IPA_PACKAGE_JSON
  if (!override) {
    console.log('IPA_PACKAGE_JSON not set; using the dependency set shipped in this tag.')
    return readJson('package.json')
  }

  if (!existsSync(override)) fail(`IPA_PACKAGE_JSON does not exist: ${override}`)

  const tagged = readJson('package.json')
  const maintained = readJson(override)

  if (maintained.name !== 'ipa') {
    fail(`${override} is not the IPA package set (name is "${maintained.name}")`)
  }

  const taggedDeps = tagged.dependencies || {}
  const changed = Object.entries(maintained.dependencies || {})
    .filter(([name, version]) => taggedDeps[name] !== version)
    .map(([name, version]) => `${name} ${taggedDeps[name] || '(new)'} -> ${version}`)

  writeJson('package.json', maintained)

  if (changed.length) {
    console.log(`Applied the maintained IPA dependency set (${changed.length} change(s)):`)
    changed.forEach(line => console.log(`  ${line}`))
  } else {
    console.log('The maintained IPA dependency set matches this tag.')
  }

  return maintained
}

/**
 * Packages master depends on that the IPA set does not have are the source of
 * every future break in this workflow. They are not fatal on their own -- the
 * rewrite table exists to cover them -- but they belong in the log.
 */
function reportDependencyDrift(masterPackageJson, ipaPackageJson) {
  const masterDeps = masterPackageJson.dependencies || {}
  const ipaDeps = ipaPackageJson.dependencies || {}
  const missing = Object.keys(masterDeps).filter(name => !ipaDeps[name])

  if (missing.length) {
    notice(
      `Packages in master but not in the IPA dependency set: ${missing.join(', ')}. ` +
        'Each one needs either a rewrite rule in this script or an entry in DEPENDENCY_OVERRIDES.'
    )
  }

  const expoMajor = majorOf(ipaDeps.expo)
  if (expoMajor !== EXPECTED_EXPO_MAJOR) {
    fail(
      `The IPA dependency set moved to Expo ${expoMajor}; this script is written for Expo ` +
        `${EXPECTED_EXPO_MAJOR}. Review DEPENDENCY_OVERRIDES and the rewrite table, then bump ` +
        'EXPECTED_EXPO_MAJOR.'
    )
  }
}

/** Add the packages the IPA set is missing. A no-op once upstream ships them itself. */
function applyDependencyOverrides(packageJson) {
  const deps = (packageJson.dependencies ||= {})
  const added = []

  for (const [name, version] of Object.entries(DEPENDENCY_OVERRIDES)) {
    if (deps[name]) continue
    deps[name] = version
    added.push(`${name}@${version}`)
  }

  if (added.length) {
    writeJson('package.json', packageJson)
    console.log(`Added to the IPA dependency set: ${added.join(', ')}`)
  }

  return added.length > 0
}

function applyRewrites(roots, rewrites) {
  const files = collectFiles(roots)
  const contents = new Map(files.map(file => [file, readFileSync(file, 'utf8')]))
  const active = []

  for (const rewrite of rewrites) {
    if (!rewrite.when()) {
      console.log(`Skipped rewrite "${rewrite.id}": not needed by this dependency set`)
      continue
    }

    if (rewrite.satisfied && [...contents.values()].some(rewrite.satisfied)) {
      console.log(`Rewrite "${rewrite.id}": already applied in this tree`)
      continue
    }

    active.push(rewrite)
    let hits = 0
    const touched = new Set()

    for (const [file, source] of contents) {
      let next = source

      for (const [from, to] of rewrite.edits) {
        let index = next.indexOf(from)
        while (index > -1) {
          next = next.slice(0, index) + to + next.slice(index + from.length)
          hits += 1
          index = next.indexOf(from, index + to.length)
        }
      }

      if (next !== source) {
        contents.set(file, next)
        touched.add(file)
      }
    }

    if (!hits) {
      fail(
        `Rewrite "${rewrite.id}" matched nothing (${rewrite.why}). Upstream changed the code it ` +
          'targets: update the rewrite table before this reaches xcodebuild.'
      )
    }

    console.log(`Rewrite "${rewrite.id}": ${hits} replacement(s) in ${[...touched].join(', ')}`)
  }

  for (const [file, source] of contents) {
    if (source !== readFileSync(file, 'utf8')) writeFileSync(file, source)
  }

  for (const rewrite of active.filter(rewrite => rewrite.residual)) {
    const offenders = [...contents]
      .filter(([, source]) => rewrite.residual.test(source))
      .map(([file]) => file)

    if (offenders.length) {
      fail(
        `Rewrite "${rewrite.id}" left unresolvable references in: ${offenders.join(', ')}. ` +
          `${rewrite.why}, so Metro would fail on these.`
      )
    }
  }
}

/** Major version of the iOS SDK this build will link against. */
function iosSdkMajor() {
  const result = spawnSync('xcrun', ['--sdk', 'iphoneos', '--show-sdk-version'], { encoding: 'utf8' })
  const match = String(result.stdout || '').match(/^(\d+)/)
  return match ? Number(match[1]) : 0
}

function guardIosSdk() {
  const sdkMajor = iosSdkMajor()
  if (!sdkMajor) {
    notice('Could not determine the iOS SDK version; skipping the SDK compatibility guard.')
    return
  }

  if (sdkMajor > MAX_SUPPORTED_IOS_SDK_MAJOR) {
    // Escape hatch for local experimentation on a machine that only has a newer
    // Xcode. The resulting app cannot launch on iOS 27 hardware, but it still
    // builds and runs in a pre-27 simulator, which is where this was verified.
    if (process.env.ALLOW_UNSUPPORTED_IOS_SDK === '1') {
      notice(
        `iOS SDK ${sdkMajor} is newer than supported (${MAX_SUPPORTED_IOS_SDK_MAJOR}); ` +
          'continuing because ALLOW_UNSUPPORTED_IOS_SDK=1. The app will trap on launch on iOS 27.'
      )
      return
    }

    fail(
      `iOS SDK ${sdkMajor} is newer than this project supports (${MAX_SUPPORTED_IOS_SDK_MAJOR}). ` +
        'Linking against iOS 27 or newer makes UIScene lifecycle adoption mandatory, and Expo 54 ' +
        'has not adopted scenes -- the app would trap in ' +
        '_UIApplicationEvaluateRuntimeIssueForNoSceneLifecycleAdoption before any app code runs. ' +
        'Pin XCODE_VERSION lower, or land scene adoption first.'
    )
  }

  console.log(`iOS SDK ${sdkMajor}: within the supported range`)
}

/**
 * Regenerate ios/ for the active dependency set.
 *
 * The tag ships an Expo 52-era project whose Objective-C AppDelegate is a no-op
 * on Expo 54 -- nothing creates a window, nothing starts React Native, and the
 * build is green all the way to a blank app.
 */
/**
 * app.json decides what prebuild writes into Info.plist as UIUserInterfaceStyle,
 * and Expo defaults it to "light" -- which pins the whole app to light mode at
 * the UIKit level, so Appearance.getColorScheme() always answers "light" and the
 * app's follow-the-system theme silently stops working.
 *
 * The checked-in Info.plist says Automatic only because nothing has regenerated
 * it in years. Tags cut before app.json declares this need it filled in.
 */
function ensureUserInterfaceStyle() {
  const appJson = readJson('app.json')
  const current = appJson.expo?.userInterfaceStyle

  if (current) {
    console.log(`app.json: userInterfaceStyle is "${current}"`)
    if (current === 'light') {
      notice('app.json pins userInterfaceStyle to "light"; the in-app follow-the-system theme cannot work.')
    }
    return
  }

  appJson.expo.userInterfaceStyle = 'automatic'
  writeJson('app.json', appJson)
  console.log('app.json: userInterfaceStyle was unset (Expo defaults to "light"); set to "automatic"')
}

/**
 * Autolinking pulls every native module into the iOS build, including the two
 * blur libraries this app only uses from .android.tsx. Both export an
 * Objective-C class named BlurView, so linking them together fails outright --
 * and @react-native-community/blur's podspec additionally pins an RCT-Folly
 * that no longer exists. react-native.config.js excludes them from iOS.
 *
 * Tags cut before that file existed need it written in, the same way the
 * dependency set is.
 */
function ensureAutolinkingConfig() {
  const target = 'react-native.config.js'

  if (existsSync(target)) {
    console.log(`${target}: already present in this tag`)
    return
  }

  const source = process.env.IPA_RN_CONFIG
  if (!source) {
    notice(`IPA_RN_CONFIG not set and this tag has no ${target}; iOS autolinking is unfiltered.`)
    return
  }

  if (!existsSync(source)) fail(`IPA_RN_CONFIG does not exist: ${source}`)

  copyFileSync(source, target)
  console.log(`${target}: written from ${source} (iOS autolinking exclusions)`)
}

function runPrebuild() {
  console.log('Regenerating ios/ with expo prebuild')
  const result = spawnSync(
    'npx',
    ['expo', 'prebuild', '--platform', 'ios', '--clean', '--no-install'],
    { stdio: 'inherit', env: { ...process.env, CI: '1' } }
  )

  if (result.status !== 0) fail('expo prebuild failed')

  for (const expected of ['ios/Bangumi/AppDelegate.swift', 'ios/Podfile', 'ios/Bangumi/Info.plist']) {
    if (!existsSync(expected)) fail(`expo prebuild did not produce ${expected}`)
  }
}

/**
 * Native settings prebuild does not derive from app.json. reanimated 4 is New
 * Architecture only, so an Expo 54 dependency set forces Fabric on.
 */
function applyNativeConfig(deps) {
  const path = 'ios/Podfile.properties.json'
  if (!existsSync(path)) fail(`Expected ${path} after prebuild`)

  const properties = readJson(path)
  const wanted = String(majorOf(deps['react-native-reanimated']) >= 4)

  if (properties.newArchEnabled === wanted) {
    console.log(`${path}: newArchEnabled is already ${wanted}`)
    return
  }

  console.log(
    `${path}: newArchEnabled ${properties.newArchEnabled ?? '(unset)'} -> ${wanted} ` +
      `(react-native-reanimated ${deps['react-native-reanimated']})`
  )
  properties.newArchEnabled = wanted
  writeJson(path, properties)
}

/** Info.plist ships a literal version string; app.json is the source of truth. */
function syncBundleVersion(appVersion) {
  const plist = 'ios/Bangumi/Info.plist'
  if (!existsSync(plist)) fail(`Expected ${plist} after prebuild`)

  execFileSync('plutil', ['-replace', 'CFBundleShortVersionString', '-string', appVersion, plist])
  console.log(`Synced ${plist} CFBundleShortVersionString to ${appVersion}`)
}

/** Xcode script phases resolve node through this file. */
function pinNodeForXcode() {
  const nodeBinary = process.execPath
  writeFileSync('ios/.xcode.env.local', `export NODE_BINARY=${JSON.stringify(nodeBinary)}\n`)
  exportEnv('NODE_BINARY', nodeBinary)
}

function sourcePhase() {
  const { masterPackageJson } = switchToIpaEnvironment()
  const ipaPackageJson = overrideIpaPackageJson()
  reportDependencyDrift(masterPackageJson, ipaPackageJson)
  const overridden = applyDependencyOverrides(ipaPackageJson)

  const appVersion = syncAppVersionToTag()

  applyRewrites(['src', 'index.js', 'index.android.js'], sourceRewrites(ipaPackageJson.dependencies || {}))

  exportEnv('APP_VERSION', appVersion)
  exportEnv('IPA_DEPENDENCIES_OVERRIDDEN', overridden ? 'true' : 'false')
}

function nativePhase() {
  const deps = readJson('package.json').dependencies || {}
  const appVersion = readJson('app.json').expo?.version

  guardIosSdk()
  ensureUserInterfaceStyle()
  ensureAutolinkingConfig()
  runPrebuild()
  applyRewrites(['ios/Bangumi/AppDelegate.swift'], nativeRewrites())
  applyNativeConfig(deps)
  syncBundleVersion(appVersion)
  pinNodeForXcode()
}

function main() {
  const phase = process.argv[2] || 'source'

  if (process.env.SOURCE_DIR) process.chdir(process.env.SOURCE_DIR)
  console.log(`Preparing ${process.cwd()} (${phase} phase)`)

  if (phase === 'source') return sourcePhase()
  if (phase === 'native') return nativePhase()

  fail(`Unknown phase: ${phase}. Use "source" or "native".`)
}

main()
